                                    '\n'
                                    '\n'
                                    'def test_table_counts(lib):\n'
                                    '    el = _elements(lib)\n'
                                    '    assert len(el) == 60773 and len(set(el)) == len(el)\n'
                                    '    assert TABLE.read_text().count("\\nSG_BOOT_SURFACE(") == 147\n'
